/**
 * lib-apps, the pure part: the framework's app directory (app-directory@1, `directory.json`, generated by
 * framework/cli/app-directory.mjs from the project manifests + external.json) and the rules every app picker follows
 * (which apps, in which order, which address, apps people add themselves). No React here, so hosts and tests share it.
 */
import directory from './directory.json';

/** How an app understands being shown inside another app: embed@1 guest, the marker read by convention, or not at all. */
export type AppEmbed = 'axf' | 'marker' | 'none';

export interface AppEntry {
  /** stable id (the project name, or the external app's id) */
  id: string;
  /** short id a host uses for its tab / view (console, pilot, axhub, …) */
  tab: string;
  label: string;
  name: string;
  icon: string;
  /** https origin, no path */
  origin: string;
  /** the page the app opens on */
  path: string;
  /** its own settings page (null = it has none a host can show) */
  settingsPath: string | null;
  embed: AppEmbed;
  /** an app that hosts others (it is never offered as a tab of itself) */
  host: boolean;
  description: string;
  from: 'manifest' | 'external' | 'custom';
  order: number;
  repo?: string;
}

const TAB = /^[a-z][a-z0-9-]{0,23}$/;
const PATH = /^\/[A-Za-z0-9._~/-]{0,120}$/;
export const MAX_APPS = 40;

/** Every app in the framework's directory (as generated; a copy, safe to change). */
export function directoryApps(): AppEntry[] {
  return ((directory as { apps: AppEntry[] }).apps ?? []).map((a) => ({ ...a }));
}

/** An https origin (http only for localhost while developing), no credentials, or null. */
export function safeOrigin(raw: unknown): string | null {
  if (typeof raw !== 'string' || !raw.trim() || raw.length > 200) return null;
  try {
    const u = new URL(raw.trim());
    const local = u.hostname === 'localhost' || u.hostname === '127.0.0.1';
    if ((u.protocol !== 'https:' && !(local && u.protocol === 'http:')) || u.username || u.password || !u.hostname) return null;
    return u.origin;
  } catch { return null; }
}

export const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 20).replace(/^[^a-z]+/, '') || 'app';

/** What a person types to add an app: a name and its address (with an optional start path). */
export interface CustomApp { tab: string; label: string; url: string; embed?: AppEmbed }

/** A custom app as a directory entry, or why not. `taken` = tab ids already in use. */
export function customEntry(c: unknown, taken: ReadonlySet<string> = new Set()): AppEntry | { error: string } {
  if (!c || typeof c !== 'object') return { error: 'not an app' };
  const o = c as Record<string, unknown>;
  const label = typeof o.label === 'string' ? o.label.trim().slice(0, 24) : '';
  if (!label) return { error: 'name it' };
  const tab = typeof o.tab === 'string' && o.tab ? o.tab : slug(label);
  if (!TAB.test(tab)) return { error: 'the id must be lowercase letters, digits and dashes' };
  if (taken.has(tab)) return { error: `“${tab}” is taken` };
  if (typeof o.url !== 'string') return { error: 'give its address' };
  const origin = safeOrigin(o.url);
  if (!origin) return { error: 'the address must be https (no user name or password)' };
  let path = '/';
  try { path = new URL(o.url.trim()).pathname || '/'; } catch { /* origin already checked */ }
  if (!PATH.test(path)) path = '/';
  const embed: AppEmbed = o.embed === 'axf' || o.embed === 'marker' ? o.embed : 'none';
  return { id: `custom-${tab}`, tab, label, name: label, icon: 'external', origin, path, settingsPath: embed === 'axf' ? '/' : null, embed, host: false, description: 'Added by hand', from: 'custom', order: 200 };
}

/** A custom app as one settings string, "tab|label|embed|url" (settings hold strings; a | in the name becomes a space). */
export const encodeCustomApp = (c: CustomApp): string => `${c.tab}|${c.label.replace(/\|/g, ' ')}|${c.embed ?? 'none'}|${c.url}`;
/** One saved custom app back (a string as above, or an object), or null. */
export function decodeCustomApp(v: unknown): CustomApp | null {
  if (v && typeof v === 'object') return v as CustomApp;
  if (typeof v !== 'string') return null;
  const [tab = '', label = '', embed = 'none', ...url] = v.split('|');
  return { tab, label, embed: embed === 'axf' || embed === 'marker' ? embed : 'none', url: url.join('|') };
}

/** Saved custom apps (a settings value: strings or objects) as entries; anything bad, or past the cap, is dropped. */
export function customApps(saved: unknown, taken: ReadonlySet<string> = new Set()): AppEntry[] {
  if (!Array.isArray(saved)) return [];
  const used = new Set(taken);
  const out: AppEntry[] = [];
  for (const raw of saved.slice(0, MAX_APPS)) {
    const e = customEntry(decodeCustomApp(raw), used);
    if ('error' in e) continue;
    used.add(e.tab);
    out.push(e);
  }
  return out;
}

/** Directory + custom apps, one per tab id and per address; a host's own app (`host: true` or at `here`) is left out. */
export function availableApps(saved: unknown, here?: string): AppEntry[] {
  const dir = directoryApps();
  const all = [...dir, ...customApps(saved, new Set(dir.map((a) => a.tab)))];
  const tabs = new Set<string>();
  const origins = new Set<string>();
  const out: AppEntry[] = [];
  for (const a of all) {
    if (a.host || (here && a.origin === here) || tabs.has(a.tab) || origins.has(a.origin)) continue;
    tabs.add(a.tab); origins.add(a.origin); out.push(a);
  }
  return out;
}

/**
 * The apps picked, in the saved order: ids that no longer exist are dropped, nothing is listed twice; with no saved
 * choice (not an array) the defaults. An empty saved list stays empty (the host decides what an empty list shows).
 */
export function pickedApps<T extends { tab: string }>(apps: readonly T[], saved: unknown, defaults: readonly string[]): T[] {
  const ids = Array.isArray(saved) ? saved.filter((x): x is string => typeof x === 'string') : [...defaults];
  const byTab = new Map(apps.map((a) => [a.tab, a]));
  const seen = new Set<string>();
  const out: T[] = [];
  for (const id of ids) {
    const a = byTab.get(id);
    if (!a || seen.has(id)) continue;
    seen.add(id); out.push(a);
  }
  return out;
}

/** Turn one app on (added at the end) or off. */
export function toggleApp(picked: readonly string[], tab: string, on: boolean): string[] {
  const rest = picked.filter((x) => x !== tab);
  return on ? [...rest, tab] : rest;
}

/** Move one picked app up (-1) or down (+1); out of range = unchanged. */
export function moveApp(picked: readonly string[], tab: string, delta: number): string[] {
  const i = picked.indexOf(tab);
  const j = i + delta;
  if (i < 0 || j < 0 || j >= picked.length) return [...picked];
  const out = [...picked];
  [out[i], out[j]] = [out[j]!, out[i]!];
  return out;
}

/** An app's address as a host saved it (settings), else its directory address. */
export function appOrigin(a: AppEntry, saved?: unknown): string {
  return (saved !== undefined && saved !== null && saved !== '' ? safeOrigin(saved) : null) ?? a.origin;
}
